function upgradeChanceFor(source, targetRow) {
  if (!source || !targetRow) return 0;
  const sourcePrice = shoePrice(source);
  const targetPrice = shoePrice(targetRow);
  if (!Number.isFinite(sourcePrice) || !Number.isFinite(targetPrice) || sourcePrice <= 0 || targetPrice <= sourcePrice) return 0;
  // Честный апгрейд: шанс напрямую зависит от отношения стоимости ставки к стоимости цели.
  // 300 ₽ → 799 ₽ = 37.5%. Более дорогая цель = меньший шанс.
  return Math.round(Math.max(1, Math.min(95, (sourcePrice / targetPrice) * 100)) * 10) / 10;
}
